import XCTest
@testable import GridFixCore

final class TAKCoTTests:XCTestCase {
    private let now=Date(timeIntervalSince1970:1792902600)
    /// Unmodified Android CotTest marker, not generated by the Swift writer.
    private let marker=#"<?xml version="1.0"?><event version="2.0" uid="M-1" type="a-h-G" how="h-g-i-g-o" time="2026-10-25T04:30:00.000Z" start="2026-10-25T04:30:00.000Z" stale="2026-10-25T04:35:00.000Z"><point lat="35.1388" lon="-78.9914" hae="0" ce="10" le="10"/><detail><contact callsign="ENEMY OP"/><link uid="ATAK-1" relation="p-p" type="a-f-G-U-C"/></detail></event>"#
    private func item(_ xml:String,own:String="me") throws ->TAKRemoteItem {
        guard case let .item(value)=TAKCoT.parse(xml,ownUID:own,now:now) else {throw TAKCoT.Failure(message:"Expected remote item")};return value
    }
    func testAndroidGoldenMarkerCreatorAffiliationAndTimestamp() throws {
        let value=try item(marker)
        XCTAssertEqual(value.id,"M-1");XCTAssertEqual(value.callsign,"ENEMY OP");XCTAssertEqual(value.affiliation,"hostile")
        XCTAssertEqual(value.creator,"ATAK-1");XCTAssertFalse(value.isContact)
        XCTAssertEqual(value.staleAt.timeIntervalSince1970,1792902900)
    }
    func testOutboundMarkerDrawingDeleteAndSelfPositionWireContract() throws {
        let name="A<B\"C&D 🙂"
        let xml=try TAKCoT.marker(uid:"wp-1",name:name,affiliation:"hostile",position:.init(lat:35.14,lon:-78.99),creatorUID:"other",creatorCallsign:"OTHER",now:now)
        XCTAssertTrue(xml.contains(#"callsign="A&lt;B&quot;C&amp;D 🙂""#));XCTAssertEqual(try item(xml).callsign,name)
        let points=[GeoPoint(lat:35,lon:-79),.init(lat:35.01,lon:-79),.init(lat:35.01,lon:-79.01)]
        for closed in [false,true] {
            let drawing=try TAKCoT.drawing(uid:"g-1",name:"PL BLUE",points:points,closed:closed,creatorUID:"other",creatorCallsign:"OTHER",now:now)
            let decoded=try item(drawing);XCTAssertEqual(decoded.points,points);XCTAssertEqual(decoded.closed,closed)
        }
        XCTAssertEqual(TAKCoT.parse(try TAKCoT.delete(uid:"wp-1",now:now),ownUID:"me",now:now),.delete("wp-1"))
        let contact=try item(TAKCoT.presence(uid:"ios-1",callsign:"IOS",now:now,position:.init(lat:35.1,lon:-79),accuracy:5))
        XCTAssertTrue(contact.isContact);XCTAssertEqual(contact.affiliation,"friendly")
        XCTAssertEqual(contact.staleAt,now.addingTimeInterval(120))
    }
    func testNoLocationPresenceEchoAndPingAreNotRemoteMarkers() throws {
        let presence=try TAKCoT.presence(uid:"ios-1",callsign:"IOS",now:now)
        XCTAssertTrue(presence.contains(#"lat="0.0000000" lon="0.0000000""#))
        XCTAssertNil(TAKCoT.parse(presence,ownUID:"other",now:now))
        XCTAssertEqual(TAKCoT.parse(presence,ownUID:"ios-1",now:now),.other)
        XCTAssertEqual(TAKCoT.parse(try TAKCoT.ping(uid:"me",now:now),ownUID:"other",now:now),.other)
        let own=try TAKCoT.marker(uid:"me-wp-1",name:"OBJ",affiliation:"none",position:.init(lat:35,lon:-79),creatorUID:"me",creatorCallsign:"ME",now:now)
        XCTAssertEqual(TAKCoT.parse(own,ownUID:"me",now:now),.other)
    }
    func testFractionalOffsetDatesAndFutureExpiryCap() throws {
        let offset=marker.replacingOccurrences(of:"2026-10-25T04:35:00.000Z",with:"2026-10-25T04:35:00.1234567+00:00")
        XCTAssertEqual(try item(offset).staleAt.timeIntervalSince1970,1792902900.1234567,accuracy:0.001)
        let future=marker.replacingOccurrences(of:"2026-10-25T04:35:00.000Z",with:"2099-01-01T00:00:00Z")
        XCTAssertEqual(try item(future).staleAt,now.addingTimeInterval(3600))
    }
    func testMalformedHostileXMLAndOversizedGeometryAreRejectedWhole() throws {
        XCTAssertNil(TAKCoT.parse("<!DOCTYPE x [<!ENTITY a 'b'>]>"+marker,ownUID:"me",now:now))
        XCTAssertNil(TAKCoT.parse(marker.replacingOccurrences(of:"35.1388",with:"95"),ownUID:"me",now:now))
        XCTAssertNil(TAKCoT.parse("<event uid=",ownUID:"me",now:now))
        XCTAssertNil(TAKCoT.parse("<event>"+String(repeating:"x",count:TAKCoT.maximumEventCharacters)+"</event>",ownUID:"me",now:now))
        let points=(0..<501).map{GeoPoint(lat:35+Double($0)*0.00001,lon:-79)}
        XCTAssertThrowsError(try TAKCoT.drawing(uid:"d",name:"D",points:points,closed:false,creatorUID:"other",creatorCallsign:"O",now:now))
        let links=points.map {"<link point='\($0.lat),\($0.lon)'/>"}.joined()
        let oversized="<event uid='d' type='u-d-f' stale='2026-10-25T04:35:00Z'><detail>\(links)</detail></event>"
        XCTAssertNil(TAKCoT.parse(oversized,ownUID:"me",now:now),"A truncated safety drawing must never masquerade as a complete one")
    }
    func testFramerHandlesEveryByteBoundaryUnicodeAndMultipleEvents() throws {
        let xml=try TAKCoT.presence(uid:"x",callsign:"JOSÉ 🙂 مرحبًا",now:now,position:.init(lat:35,lon:-79),accuracy:5)
        let bytes=Data(xml.utf8)
        var stream=TAKCoTStream(),events:[String]=[]
        for byte in bytes {events += try stream.feed(Data([byte]))}
        XCTAssertEqual(events,[xml]);XCTAssertEqual(try item(events[0]).callsign,"JOSÉ 🙂 مرحبًا")
        XCTAssertEqual(try stream.feed(Data((xml+"<event uid='x' type='t-x-c-t'/>"+xml).utf8)).count,3)
    }
    func testFramerIgnoresFakeEndsInQuotesCommentsCDATAAndRecoversAfterLimit() throws {
        var stream=TAKCoTStream()
        let xml="<event uid='x' type='t-x-c-t' label=' > </event>'><detail><!-- </event> --><remarks><![CDATA[</event>]]></remarks></detail></event>"
        XCTAssertEqual(try stream.feed(Data(xml.utf8)),[xml])
        XCTAssertTrue(try stream.feed(Data("junk<eve".utf8)).isEmpty)
        XCTAssertEqual(try stream.feed(Data("nt uid='x'/>".utf8)),["<event uid='x'/>"])
        var small=TAKCoTStream(maximumBytes:1024)
        XCTAssertThrowsError(try small.feed(Data(repeating:65,count:1025)));XCTAssertEqual(small.bufferedBytes,0)
        XCTAssertEqual(try small.feed(Data("<event/>".utf8)),["<event/>"])
    }
    func testHostileDeclarationsAreRejectedAcrossEveryByteSplitBeforeEvent() throws {
        for declaration in ["<!DOCTYPE x>", "<!DoCtYpE x>", "<!ENTITY x 'x'>"] {
            let bytes=Data((declaration+"<event uid='x'/>").utf8)
            for split in 1..<bytes.count {
                var stream=TAKCoTStream()
                XCTAssertThrowsError(try {
                    _ = try stream.feed(bytes.prefix(split))
                    _ = try stream.feed(bytes.dropFirst(split))
                }())
                XCTAssertEqual(stream.bufferedBytes,0)
                XCTAssertEqual(try stream.feed(Data("<event/>".utf8)),["<event/>"])
            }
        }
        XCTAssertNil(TAKCoT.parse(marker.replacingOccurrences(of:"<detail>",with:"<point lat='invalid' lon='-79'/><detail>"),ownUID:"me",now:now))
    }
    func testRemoteSceneReplacementDeletionCapacityAndMonotonicExpiry() throws {
        var scene=TAKRemoteScene()
        for index in 0...1001 {
            let value=TAKRemoteItem(id:"u\(index)",callsign:"U",affiliation:"unknown",points:[.init(lat:35,lon:-79)],closed:false,isContact:false,staleAt:now.addingTimeInterval(120),creator:nil)
            scene.apply(.item(value),now:now,uptime:100)
        }
        XCTAssertEqual(scene.items.count,1000)
        let update=TAKRemoteItem(id:"u0",callsign:"Changed",affiliation:"friendly",points:[.init(lat:36,lon:-79)],closed:false,isContact:true,staleAt:now.addingTimeInterval(120),creator:nil)
        scene.apply(.item(update),now:now,uptime:100);XCTAssertEqual(scene.items[0].callsign,"Changed")
        scene.apply(.delete("u0"),now:now,uptime:101);XCTAssertEqual(scene.items.count,999)
        XCTAssertTrue(scene.expire(now:now.addingTimeInterval(-600),uptime:221));XCTAssertTrue(scene.items.isEmpty)
        scene.apply(.item(update),now:now,uptime:100)
        XCTAssertTrue(scene.expire(now:now,uptime:5));XCTAssertTrue(scene.items.isEmpty)
    }
}
